import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BlogPost } from '@/app/blog/[id]/blog-post'
import type { Comment, Post } from '@/types/blog'

export const dynamicParams = true
export const revalidate = 300

type BlogPostPageProps = PageProps<'/blog/[id]'>

export async function generateStaticParams() {
  const posts: Post[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts'
  ).then((res) => res.json())

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

async function getPost(id: string): Promise<Post | null> {
  const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
    next: { revalidate: 300 },
  })

  if (!res.ok) {
    return null
  }

  const post: Post = await res.json()
  if (!post?.id) {
    return null
  }

  return post
}

async function getComments(id: string): Promise<Comment[]> {
  const res = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}/comments`,
    { next: { revalidate: 300 } }
  )

  if (!res.ok) {
    return []
  }

  return res.json()
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  const post = await getPost(id)

  if (!post) {
    return {
      title: 'Not Found - My Blog',
    }
  }

  const description = post.body.substring(0, 160)

  return {
    title: `${post.title} - My Blog`,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params
  const post = await getPost(id)

  if (!post) {
    notFound()
  }

  const comments = await getComments(id)

  return <BlogPost post={post} comments={comments} />
}

